  "part": {
    "name": "Cross-strut clamp assembly",
    "description": "Three-solid mechanical part/assembly consisting of a long vertical strut, a long diagonal strut, and a central clamp block that captures/locates both struts and provides a through-bolt interface (with counterbores) for tightening.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Central clamp block is largely symmetric about X=0 and Z=0 planes; overall part is not fully symmetric due to asymmetric end-hole/feature pattern on the diagonal strut."
  },
